get(key) {
  const now = clock()
  const entry = entries.get(key)
  if (entry === undefined) return undefined
  if (now > entry.expiresAt) {
    // expired: treat as a miss and drop the entry
    entries.delete(key)
    return undefined
  }
  // touch: re-insert so Map order tracks recency (last = most recent)
  entries.delete(key)
  entries.set(key, entry)
  entry.lastUsed = now
  return entry.value
},

